import '../../../shared/repositories/repositories.dart';
import '../../domain/entities.dart';
import '../database/app_database.dart';
import '../database/mappers/organization_mappers.dart';
final class LocalUserRepository implements UserRepository { const LocalUserRepository(this.dao); final UserDao dao; @override Future<OrganizationUser?> getUserById(String id) async=>(await dao.getUserById(id))?.toOrganizationUserDomain(); @override Future<List<OrganizationUser>> getUsers() async=>(await dao.getUsers()).map((e)=>e.toOrganizationUserDomain()).toList(); @override Future<List<OrganizationUser>> getActiveUsers() async=>(await dao.getActiveUsers()).map((e)=>e.toOrganizationUserDomain()).toList(); @override Future<List<OrganizationUser>> getUsersByDepartment(String id) async=>(await dao.getUsersByDepartment(id)).map((e)=>e.toOrganizationUserDomain()).toList(); @override Future<List<OrganizationUser>> getDirectReports(String id) async=>(await dao.getDirectReports(id)).map((e)=>e.toOrganizationUserDomain()).toList(); @override Future<List<OrganizationUser>> getUsersByTeam(String id) async=>(await dao.getUsersByTeam(id)).map((e)=>e.toOrganizationUserDomain()).toList(); }
